import {
  Outlet,
  ScrollRestoration,
  createRootRoute,
} from '@tanstack/react-router'
import { Meta, Scripts } from '@tanstack/start'
import * as React from 'react'

export const Route = createRootRoute({
  component: RootComponent,
})

function RootComponent() {
  return (
    <RootDocument>
      <Outlet />
    </RootDocument>
  )
}

function RootDocument({ children }: { children: React.ReactNode }) {
  return (
    <html>
      <head>
        <Meta />
      </head>
      <body>
        {children}
        <ScrollRestoration />
        <Scripts />
      </body>
    </html>
  )
}

import Database from 'better-sqlite3'
import path from 'path'

// Initialize the database connection
const dbPath = path.resolve(process.cwd(), 'sqlite.db')
export const db = new Database(dbPath)

// Initialize the table
db.exec(`
  CREATE TABLE IF NOT EXISTS counter (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    count INTEGER NOT NULL DEFAULT 0
  )
`)

// Insert initial row if it doesn't exist
db.exec(`
  INSERT OR IGNORE INTO counter (id, count) VALUES (1, 0)
`)

export function getCount(): number {
  const row = db.prepare('SELECT count FROM counter WHERE id = 1').get() as { count: number }
  return row.count
}

export function incrementCount(): number {
  db.prepare('UPDATE counter SET count = count + 1 WHERE id = 1').run()
  return getCount()
}

import { createFileRoute, useRouter } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/start'
import * as fs from 'fs'

const getCountFn = createServerFn('GET', async () => {
  const { getCount } = await import('../db')
  return getCount()
})

const incrementCountFn = createServerFn('POST', async () => {
  const { incrementCount } = await import('../db')
  return incrementCount()
})

export const Route = createFileRoute('/')({
  loader: async () => {
    const count = await getCountFn()
    return { count }
  },
  component: Home,
})

function Home() {
  const router = useRouter()
  const state = Route.useLoaderData()

  const onIncrement = async () => {
    await incrementCountFn()
    router.invalidate()
  }

  return (
    <div>
      <h1>Counter</h1>
      <p>Count: <span data-testid="count">{state.count}</span></p>
      <button data-testid="increment" onClick={onIncrement}>
        Increment
      </button>
    </div>
  )
}
